(() => {
'use strict';
const markup="<span class=\"eyebrow\">Riêng cho bạn · 30 ngày gần đây</span><h1>Khẩu vị của bạn</h1><p>Theo đánh giá và lịch đặt món của bạn.</p><section class=\"card summary\"><span class=\"eyebrow\">Tổng hợp</span><p><strong>Bạn thường thích món kho, vị vừa và thịt mềm.</strong></p><p>8 đánh giá · 6 bữa. Dữ liệu còn ít.</p><span class=\"tiny\">Dữ liệu mẫu</span></section><section class=\"grid\"><article class=\"card\"><h2>Món ăn</h2><div class=\"tabs\" role=\"group\" aria-label=\"Loại biểu đồ\"><button id=\"liked\" aria-pressed=\"true\">Món yêu thích</button><button id=\"frequent\" aria-pressed=\"false\">Món hay đặt</button></div><p class=\"tiny\" id=\"chart-description\" role=\"status\" aria-atomic=\"true\">Dựa trên điểm bạn tự đánh giá; gọi nhiều chưa có nghĩa là thích.</p><div id=\"chart\" aria-label=\"Biểu đồ món ăn\"></div><details><summary>Dữ liệu này được hiểu thế nào?</summary><p class=\"tiny\">Mỗi món gắn riêng với một quán. “Yêu thích” dùng điểm đánh giá của bạn, “Hay đặt” dùng số bữa có món đó. Các số trong bản xem trước đều được tạo để minh họa cách trình bày.</p></details></article><article class=\"card\"><h2>Những cảm nhận thường gặp</h2><p class=\"tiny\">Các ý bạn đã tự chọn khi đánh giá.</p><div class=\"tags\"><span class=\"tag\">Vừa miệng · 5 lần</span><span class=\"tag\">Thịt mềm · 3 lần</span><span class=\"tag\">Ít dầu · 2 lần</span></div><div class=\"rule\"><span class=\"eyebrow\">Có trong menu hôm nay</span><h2 style=\"margin-top:12px\">Thịt kho trứng</h2><p>Cơm nhà An · 35.000đ</p><p>Bạn đã chấm món này trung bình 4,7/5 qua 3 lần đánh giá. Món hiện có trong menu hôm nay.</p><a class=\"primary\" href=\"#menu\" data-taste-route=\"menu\">Xem menu hôm nay →</a><p class=\"tiny\" style=\"margin-top:16px\">Gợi ý dựa trên dữ liệu mẫu. Trang này chỉ dành cho bạn.</p></div></article></section><section class=\"card\" style=\"margin-top:20px\"><h2>Bữa chưa đánh giá</h2><p>Đánh giá bữa gần đây để bổ sung khẩu vị.</p><a href=\"#history\" data-taste-route=\"history\">Đánh giá một bữa gần đây</a></section>";
const rows={liked:[['Thịt kho trứng','Cơm nhà An','4,7 / 5 · 3 đánh giá',94],['Gà nướng mật ong','Cơm nhà An','4,3 / 5 · 3 đánh giá',86],['Đậu hũ sốt nấm','Bếp cô Tư','4,0 / 5 · 2 đánh giá',80]],frequent:[['Gà nướng mật ong','Cơm nhà An','6 bữa',100],['Thịt kho trứng','Cơm nhà An','4 bữa',67],['Cá kho tộ','Bếp cô Tư','3 bữa',50]]};
let chartMode='liked';
window.tasteScreen=()=>'<div class="taste-surface">'+markup+'</div>';
window.bindTastePreview=root=>{
 const draw=mode=>{chartMode=mode;root.querySelector('#chart').innerHTML=rows[mode].map(([name,shop,detail,width])=>'<div class="row"><strong>'+name+'</strong><span class="tiny">'+detail+'</span></div><p class="tiny" style="margin-bottom:0">'+shop+'</p><div class="bar"><b style="width:'+width+'%"></b></div>').join('');
 for(const id of ['liked','frequent'])root.querySelector('#'+id).setAttribute('aria-pressed',String(mode===id));
 root.querySelector('#chart-description').textContent=mode==='liked'?'Điểm bạn tự đánh giá; số lần đặt không thể hiện mức yêu thích.':'Số bữa đã đặt món này; được tách riêng khỏi điểm yêu thích.';};
 for(const id of ['liked','frequent'])root.querySelector('#'+id).onclick=()=>draw(id);
 root.querySelectorAll('[data-taste-route]').forEach(a=>a.onclick=e=>{e.preventDefault();go(a.dataset.tasteRoute)});
 draw(chartMode);
};
})();
